module autonomous_car (\n    input clk,\n    input rst_n,\n    input start,\n    input [15:0] N,\n    input [15:0] M,\n    input [15:0] R,\n    input [1:0] car_lane [0:7],\n    input [15:0] car_len [0:7],\n    input [15:0] car_pos [0:7],\n    output reg result_valid,\n    output reg [31:0] result_safety_factor,\n    output reg result_impossible\n);\n\n    // State definitions\n    localparam [3:0] IDLE            = 4'd0;\n    localparam [3:0] LOAD            = 4'd1;\n    localparam [3:0] CHECK_FEASIBLE  = 4'd2;\n    localparam [3:0] BINARY_SEARCH   = 4'd3;\n    localparam [3:0] UPDATE          = 4'd4;\n    localparam [3:0] DONE            = 4'd5;\n    localparam [3:0] IMPOSSIBLE_ST   = 4'd6;\n    reg [3:0] state;\n\n    // Parameters\n    localparam [3:0] MAX_CARS_PER_LANE = 4'd3;\n    localparam [4:0] MAX_ITERATIONS    = 5'd16;\n    localparam [31:0] R_LOW          = 32'd0;\n\n    // Internal storage\n    reg [15:0] R_scaled_base;\n    reg [31:0] L0_scaled;\n    reg [31:0] R_scaled;\n\n    // Lane arrays\n    reg [31:0] lane0_pos [0:3];\n    reg [31:0] lane0_len [0:3];\n    reg [1:0]  lane0_count;\n    reg [31:0] lane1_pos [0:3];\n    reg [31:0] lane1_len [0:3];\n    reg [1:0]  lane1_count;\n\n    // Binary search vars\n    reg [31:0] low;\n    reg [31:0] high;\n    reg [31:0] mid;\n    reg [4:0]  iter_count;\n\n    // Feasibility flags\n    reg current_feasible;\n    reg base_feasible;\n\n    integer i, j;\n\n    // Combinatorial feasibility check\n    always @(*) begin\n        // Initialize all interval arrays\n        reg [31:0] lane0_start[0:4];\n        reg [31:0] lane0_end[0:4];\n        reg [2:0]  lane0_intervals = 0;\n        reg [31:0] lane1_start[0:4];\n        reg [31:0] lane1_end[0:4];\n        reg [2:0]  lane1_intervals = 0;\n\n        // Lane 0 interval calculation\n        if (lane0_count == 2'd0) begin\n            lane0_start[0] = 32'd0;\n            lane0_end[0] = R_scaled - L0_scaled;\n            lane0_intervals = (R_scaled >= L0_scaled) ? 3'd1 : 3'd0;\n        end else begin\n            // Left segment\n            if (lane0_pos[0] >= (L0_scaled + mid)) begin\n                lane0_start[lane0_intervals] = 32'd0;\n                lane0_end[lane0_intervals] = lane0_pos[0] - L0_scaled - mid;\n                lane0_intervals = lane0_intervals + 1;\n            end\n\n            // Middle segments\n            for (i = 0; i < lane0_count; i = i + 1) begin\n                if (i < (lane0_count - 1)) begin\n                    if ((lane0_pos[i] + lane0_len[i] + mid) <= (lane0_pos[i+1] - L0_scaled - mid)) begin\n                        lane0_start[lane0_intervals] = lane0_pos[i] + lane0_len[i] + mid;\n                        lane0_end[lane0_intervals] = lane0_pos[i+1] - L0_scaled - mid;\n                        lane0_intervals = lane0_intervals + 1;\n                    end\n                end\n            end\n\n            // Right segment\n            if ((lane0_pos[lane0_count-1] + lane0_len[lane0_count-1] + mid) <= R_scaled) begin\n                lane0_start[lane0_intervals] = lane0_pos[lane0_count-1] + lane0_len[lane0_count-1] + mid;\n                lane0_end[lane0_intervals] = R_scaled - L0_scaled;\n                lane0_intervals = lane0_intervals + 1;\n            end\n        end\n\n        // Lane 1 interval calculation (same logic)\n        if (lane1_count == 2'd0) begin\n            lane1_start[0] = 32'd0;\n            lane1_end[0] = R_scaled - L0_scaled;\n            lane1_intervals = (R_scaled >= L0_scaled) ? 3'd1 : 3'd0;\n        end else begin\n            if (lane1_pos[0] >= (L0_scaled + mid)) begin\n                lane1_start[lane1_intervals] = 32'd0;\n                lane1_end[lane1_intervals] = lane1_pos[0] - L0_scaled - mid;\n                lane1_intervals = lane1_intervals + 1;\n            end\n\n            for (i = 0; i < lane1_count; i = i + 1) begin\n                if (i < (lane1_count - 1)) begin\n                    if ((lane1_pos[i] + lane1_len[i] + mid) <= (lane1_pos[i+1] - L0_scaled - mid)) begin\n                        lane1_start[lane1_intervals] = lane1_pos[i] + lane1_len[i] + mid;\n                        lane1_end[lane1_intervals] = lane1_pos[i+1] - L0_scaled - mid;\n                        lane1_intervals = lane1_intervals + 1;\n                    end\n                end\n            end\n\n            if ((lane1_pos[lane1_count-1] + lane1_len[lane1_count-1] + mid) <= R_scaled) begin\n                lane1_start[lane1_intervals] = lane1_pos[lane1_count-1] + lane1_len[lane1_count-1] + mid;\n                lane1_end[lane1_intervals] = R_scaled - L0_scaled;\n                lane1_intervals = lane1_intervals + 1;\n            end\n        end\n\n        // Overlap check\n        current_feasible = 1'b0;\n        for (i = 0; i < lane0_intervals; i = i + 1) begin\n            for (j = 0; j < lane1_intervals; j = j + 1) begin\n                if ((lane0_start[i] <= lane1_end[j]) && (lane1_start[j] <= lane0_end[i])) begin\n                    current_feasible = 1'b1;\n                end\n            end\n        end\n    end\n\n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result_valid <= 1'b0;\n            result_impossible <= 1'b0;\n            result_safety_factor <= 32'd0;\n            L0_scaled <= 32'd0;\n            R_scaled <= 32'd0;\n            lane0_count <= 2'd0;\n            lane1_count <= 2'd0;\n            for (i = 0; i < 4; i = i + 1) begin\n                lane0_pos[i] <= 32'd0;\n                lane0_len[i] <= 32'd0;\n                lane1_pos[i] <= 32'd0;\n                lane1_len[i] <= 32'd0;\n            end\n            low <= 32'd0;\n            high <= 32'd0;\n            mid <= 32'd0;\n            iter_count <= 5'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    result_valid <= 1'b0;\n                    if (start) begin\n                        state <= LOAD;\n                    end\n                end\n\n                LOAD: begin\n                    // Scale inputs to Q16.16 format\n                    L0_scaled <= {car_len[0], 16'd0};\n                    R_scaled_base <= R;\n                    R_scaled <= {R, 16'd0};\n\n                    // Filter cars into lanes (skip autonomous car at index 0)\n                    lane0_count <= 2'd0;\n                    lane1_count <= 2'd0;\n                    for (i = 1; i < 8; i = i + 1) begin\n                        if (i < M) begin\n                            if (car_lane[i] == 2'd0) begin\n                                if (lane0_count < MAX_CARS_PER_LANE) begin\n                                    lane0_pos[lane0_count] <= {car_pos[i], 16'd0};\n                                    lane0_len[lane0_count] <= {car_len[i], 16'd0};\n                                    lane0_count <= lane0_count + 1;\n                                end\n                            end else if (car_lane[i] == 2'd1) begin\n                                if (lane1_count < MAX_CARS_PER_LANE) begin\n                                    lane1_pos[lane1_count] <= {car_pos[i], 16'd0};\n                                    lane1_len[lane1_count] <= {car_len[i], 16'd0};\n                                    lane1_count <= lane1_count + 1;\n                                end\n                            end\n                        end\n                    end\n                    state <= CHECK_FEASIBLE;\n                end\n\n                CHECK_FEASIBLE: begin\n                    mid <= 32'd0;  // Check with δ=0\n                    state <= UPDATE;\n                end\n\n                BINARY_SEARCH: begin\n                    if (iter_count >= MAX_ITERATIONS || low >= high) begin\n                        state <= DONE;\n                    end else begin\n                        mid <= (low + high + 1) >> 1;  // Ceiling division\n                        state <= UPDATE;\n                    end\n                end\n\n                UPDATE: begin\n                    if (state == CHECK_FEASIBLE) begin\n                        base_feasible <= current_feasible;\n                        if (!current_feasible) begin\n                            state <= IMPOSSIBLE_ST;\n                        end else begin\n                            low <= 32'd0;\n                            high <= R_scaled;\n                            iter_count <= 5'd0;\n                            state <= BINARY_SEARCH;\n                        end\n                    end else begin\n                        iter_count <= iter_count + 1;\n                        if (current_feasible) begin\n                            low <= mid;\n                        end else begin\n                            high <= mid - 1;\n                        end\n                        state <= BINARY_SEARCH;\n                    end\n                end\n\n                DONE: begin\n                    result_valid <= 1'b1;\n                    result_impossible <= 1'b0;\n                    result_safety_factor <= low;\n                    state <= IDLE;\n                end\n\n                IMPOSSIBLE_ST: begin\n                    result_valid <= 1'b1;\n                    result_impossible <= 1'b1;\n                    result_safety_factor <= 32'd0;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule